import{z as i,x as o,o as E,c as n,q as t,j as m,D as e,d as A,s as l,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"shared memory 与寄存器预算","description":"","frontmatter":{"title":"shared memory 与寄存器预算","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ak-smem-register-budget.md","filePath":"llm/ak-smem-register-budget.md","lastUpdated":1791413859000}'),D={name:"llm/ak-smem-register-budget.md"};function d(p,a,h,C,c,_){const r=o("Mermaid");return E(),n("div",null,[a[2]||(a[2]=t('<h1 id="shared-memory-与寄存器预算" tabindex="-1">shared memory 与寄存器预算 <a class="header-anchor" href="#shared-memory-与寄存器预算" aria-label="Permalink to &quot;shared memory 与寄存器预算&quot;">​</a></h1><div class="epigraph"><p>片上存储是一份签了额度的预算：smem 与寄存器每多要一块，能同时驻留的线程块就少一个。</p><footer>—— 据 NVIDIA CUDA C++ 编程指南与 CUTLASS 文档整理</footer></div><p><a href="/llm/ak-memory-access">上一课</a>把快慢记成了字节账，收在「复用要落在确定性层级」。本课进到片上，把 tile 多大才装得下、装下之后还剩多少并发算清楚。这一步不做，tile 一开大就溢出、一开小就挨饿，前两课省下的字节全在片上这一层赔回去。基础机制单元到此三课：骨架、账本、预算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的 \\(O(n^2d^2/M)\\) 里，\\(M\\) 是片上 SRAM 容量；但 \\(M\\) 不是给你一个人的。A100 每个 SM 有 \\(192\\,\\mathrm{KB}\\) smem 与 \\(64\\mathrm{K}\\) 个 32 位寄存器，能同时驻留的线程块由每个块要走的份额决定。tile 开太大，smem 超限，编译器把放不下的数据溢出到 local memory——物理上就是 HBM，上一课省掉的来回原路吐回，而且是在最疼的路径上。tile 装得下、但份额大到每个 SM 只住得进一个块，占用率就掉到谷底：访存延迟数百周期，没有别的块顶上来盖住，SM 一半时间在干等。缺口是：tile 尺寸不是性能参数，是预算约束下的解。</p><p><span class="marginnote">术语翻译：smem 是每个计算单元身边的小黑板，读写极快但只有几百 KB。放不下的数据会被编译器「溢出」到 local memory——名字听着像本地，物理上就在显存里，比小黑板慢几十倍。所谓溢出，就是把省下的快递费又全付了回去。</span></p><h3 id="两本预算表" tabindex="-1">两本预算表 <a class="header-anchor" href="#两本预算表" aria-label="Permalink to &quot;两本预算表&quot;">​</a></h3><p>smem 的住户是 Q、K、V、O 四个块，加上流水线的缓冲份数；寄存器的住户是输出累加器与中间分数矩阵，摊到 warp 内每个线程头上。两本表都要乘上并发块数，再对上每 SM 的额度。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算三步。第一步数 smem：四个块的面积约 \\((B_r+B_c+B_c+B_r)\\,d\\) 个元素，fp16 每个两字节；取 \\(B_r=B_c=128\\)、\\(d=128\\)，单份就是 \\(128\\,\\mathrm{KB}\\)，A100 上双缓冲根本装不下——要么砍 tile，要么砍流水级数。第二步数寄存器：累加器 \\(O\\)（\\(B_r\\times d\\)）与分数块 \\(S\\)（\\(B_r\\times B_c\\)）分摊到线程，每线程不超过 255 个寄存器，整 SM 不超过 \\(64\\mathrm{K}\\)。第三步算占用率：每块的 smem 与寄存器份额决定每 SM 驻几个块，目标通常是至少两个，让一个块的访存段被另一个块的计算段盖住。</p><p><span class="marginnote">直觉类比：一个 SM 像一间厨房——smem 是灶台面积，寄存器是每位厨师的随身工具格。一份「菜谱」（线程块）占的灶台越大，厨房里同时能容纳的厨师组越少；只剩一组时，等食材的间隙没人顶班，灶台就凉了。</span></p>',11)),(E(),m(s,null,{default:e(()=>[l(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%80%99%E9%80%89%20tile%20%E5%B0%BA%E5%AF%B8%22%5D%20--%3E%20B%5B%22smem%EF%BC%9A%E5%9B%9B%E5%9D%97%E9%9D%A2%E7%A7%AF%20%C3%97%20%E6%B5%81%E6%B0%B4%E4%BB%BD%E6%95%B0%22%5D%0A%20%20B%20--%3E%20C%7B%22%E8%A3%85%E5%BE%97%E4%B8%8B%3F%22%7D%0A%20%20C%20--%3E%7C%E5%90%A6%7C%20D%5B%22%E7%A0%8D%20tile%20%E6%88%96%E7%A0%8D%20stage%EF%BC%8C%E9%87%8D%E6%9D%A5%22%5D%0A%20%20C%20--%3E%7C%E6%98%AF%7C%20E%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%EF%BC%9A%E7%B4%AF%E5%8A%A0%E5%99%A8%E6%91%8A%E5%88%B0%E6%AF%8F%E7%BA%BF%E7%A8%8B%20%E2%89%A4255%22%5D%0A%20%20E%20--%3E%20F%7B%22%E6%AF%8F%20SM%20%E8%83%BD%E9%A9%BB%20%E2%89%A52%20%E5%9D%97%3F%22%7D%0A%20%20F%20--%3E%7C%E5%90%A6%7C%20D%0A%20%20F%20--%3E%7C%E6%98%AF%7C%20G%5B%22%E9%94%81%E5%AE%9A%E5%80%99%E9%80%89%EF%BC%8C%E8%BF%9B%E5%9F%BA%E5%87%86%E7%BD%91%E6%A0%BC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[A("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"为什么占用率是注意力内核的命门：内核的循环是「载入 KV 块（纯访存）→ 算 GEMM 与 softmax（纯计算）」交替的，单块视角下两段互相干等；靠的是同 SM 上的另一块在错开的相位上互补。块数掉到一，流水就断成串行。错法因此都长一个样：把 \\(B_c\\) 开到 512 追求「一次多搬点」，smem 爆掉、local memory 流量在剖析器里暴涨；或者三级流水占三份缓冲，一个 SM 只剩一个块，尾部排水把收益吃光。寄存器一侧同样：为了让 softmax 归约少走 smem 而把手写内联堆上去，每线程寄存器顶格，占用率照样塌。",-1)),(E(),m(s,null,{default:e(()=>[l(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20B1%5B%22%E7%BA%BF%E7%A8%8B%E5%9D%97%201%20%E7%9A%84%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20%20%20A1%5B%22%E8%BD%BD%E5%85%A5%20KV%20%E5%9D%97%3A%20%E8%AE%BF%E5%AD%98%22%5D%20--%3E%20A2%5B%22GEMM%20%E4%B8%8E%20softmax%3A%20%E8%AE%A1%E7%AE%97%22%5D%20--%3E%20A3%5B%22%E8%BD%BD%E5%85%A5%E4%B8%8B%E4%B8%80%E5%9D%97%3A%20%E8%AE%BF%E5%AD%98%22%5D%0A%20%20end%0A%20%20subgraph%20B2%5B%22%E7%BA%BF%E7%A8%8B%E5%9D%97%202%20%E7%9A%84%E7%9B%B8%E4%BD%8D%20(%E9%94%99%E5%BC%80)%22%5D%0A%20%20%20%20C1%5B%22%E8%AE%A1%E7%AE%97%3A%20%E7%9B%96%E4%BD%8F%E5%9D%97%201%20%E7%9A%84%E8%AE%BF%E5%AD%98%22%5D%20--%3E%20C2%5B%22%E8%BD%BD%E5%85%A5%3A%20%E7%9B%96%E4%BD%8F%E5%9D%97%201%20%E7%9A%84%E8%AE%A1%E7%AE%97%22%5D%20--%3E%20C3%5B%22%E8%AE%A1%E7%AE%97%22%5D%0A%20%20end%0A%20%20A1%20--%3E%20OCC%5B%22%E5%90%8C%20SM%20%E4%B8%A4%E5%9D%97%E4%BA%92%E8%A1%A5%2C%20SM%20%E4%B8%8D%E9%97%B2%22%5D%0A%20%20C1%20--%3E%20OCC%0A%20%20ONE%5B%22%E4%BB%BD%E9%A2%9D%E5%A4%AA%E5%A4%A7%E5%8F%AA%E5%89%A9%201%20%E5%9D%97%E6%97%B6%3A%20%E4%B8%A4%E6%AE%B5%E4%BA%92%E7%9B%B8%E5%B9%B2%E7%AD%89%22%5D%20--%3E%20BAD%5B%22%E6%B5%81%E6%B0%B4%E6%96%AD%E6%88%90%E4%B8%B2%E8%A1%8C%2C%20%E5%8D%A0%E7%94%A8%E7%8E%87%E5%A1%8C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">Hopper 把每 SM 的 smem 提到 \\(228\\,\\mathrm{KB}\\)，寄存器仍是 \\(64\\mathrm{K}\\)——FlashAttention-3 的 warp 特化与异步搬运，正是拿着这份更大的预算重排流水，见 <a href="/llm/flashattention-3">FlashAttention-3</a>。换架构要重跑一遍本课的预算，不是常数平移。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>预算是静态约束，给出的是候选集合；谁是候选里的赢家要靠基准说话，那是后面测量与调优两课的事。寄存器怎么分是编译器的裁决，源码一样、编译选项不同，分配结果就会翻盘，剖析器里的 spill 与 occupancy 计数要当成验收项看。warp 内怎么归约、MMA 原子怎么对齐，属于体系结构与 CUTLASS 的细节，本课只把它们当作 tile 尺寸的下界约束。不同硬件的额度表不同，这里先记住流程，移植一课再谈表怎么换。</p><p><span class="marginnote">常见误区：初学者容易以为「tile 越大越快」。tile 大一次搬的数据是多，但灶台与工具格马上超支——要么溢出到慢几十倍的显存，要么每个 SM 只剩一个块、访存延迟没人盖。tile 是预算约束下解出来的，不是拍脑袋定大的。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>tile 尺寸是预算约束下的解：smem 面积、寄存器份额、占用率三本表联立。</li><li>溢出到 local memory 就是溢出到 HBM，访存优化的成果原路返还。</li><li>占用率掉到每 SM 一个块，流水断成串行，访存延迟没人盖。</li><li>流水份数与块面积共抢 smem，双缓冲不是免费的。</li><li>换架构要重跑预算流程：Hopper 的 \\(228\\,\\mathrm{KB}\\) 与 A100 的 \\(192\\,\\mathrm{KB}\\) 是两张表。</li><li>出处：NVIDIA CUDA C++ Programming Guide（smem 与寄存器上限）；CUTLASS 文档口径。</li></ul>',6))])}const F=i(D,[["render",d]]);export{u as __pageData,F as default};
